import driver, numpy as np, math
mj=__import__('mujoco')
def fixed(ax, secs=3.0):
    r=driver.build(); mj.mj_resetDataKeyframe(r.model,r.data,1); mj.mj_forward(r.model,r.data)
    dt=r._sim_dt(); freq=2.0; omega=2*math.pi*freq
    home=r._home_q.copy(); order=r._leg_order
    phase={order[0]:0.0,order[3]:0.0,order[1]:math.pi,order[2]:math.pi}
    t0=r.data.time; hx=[]
    while r.data.time-t0<secs:
        t=r.data.time; q=home.copy()
        for li,leg in enumerate(order):
            phi=omega*t+phase[leg]; sw=max(0,math.sin(phi)); st=min(0,math.sin(phi))
            b=li*3
            q[b+1]+= -1.0*ax*(sw-0.5*(-st))
            q[b+2]-= abs(ax)*1.4*sw
